{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Tetrabenazine absolute oral bioavailability in fed patients was 8.5% after a single 50 mg oral dose, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Felodipine absolute oral bioavailability in cirrhotic patients was 17.0% after a 10 mg oral dose versus IV, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tegaserod absolute oral bioavailability under fasted conditions is approximately 10%, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Felodipine absolute oral bioavailability in fasted hypertensive patients was 12.1 ± 6.8% after a 10 mg tablet, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Delmopinol oral bioavailability after swallowing is very low in humans, consistent with F<20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Colesevelam systemic bioavailability is negligible in healthy volunteers, with minimal absorption, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nimodipine absolute oral bioavailability was 3.5 ± 0.97% after a 30 mg fasted oral tablet, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Testosterone undecanoate, a lipophilic ester prodrug, had absolute oral bioavailability of 6.83 ± 3.32% in young women, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Oseltamivir carboxylate absolute bioavailability after oral oseltamivir prodrug was 79.0 ± 11.6% in healthy volunteers, above 20%; however, oseltamivir is polar and highly soluble, with low transferability to the lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly lipophilic, poorly soluble neutral ester/lactone (orlistat-like). Multiple human absolute oral bioavailability measurements in relevant analogues—including lipophilic ester prodrugs and poorly absorbed drugs—are all below 20% (testosterone undecanoate 6.8%, nimodipine 3.5%, felodipine 12-17%, tetrabenazine 0.1-8.5%, tegaserod 10%, delmopinol very low, colesevelam negligible). The only high-bioavailability analogue (oseltamivir) has low transferability and opposite polarity/solubility. Therefore F<20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself; prediction relies on analogue transfer.",
    "The query's specific absorption mechanism (e.g., lymphatic uptake, intestinal hydrolysis, efflux) is not directly measured.",
    "Food effect and formulation impact on the query's oral bioavailability are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

